# -*- coding: utf-8 -*-
from gcommon import *
PA = 'parent'

def AGE(slug, title, desc, levels, goals, intro, traits, suits, session, avoid, ex, summ, sort):
    return G(slug, PA, 'age', title, desc, levels, 'حسب العمر والمرحلة', goals, intro,
        [H('ماذا يميّز هذه المرحلة؟'), TABLE(['الجانب', 'ما تلاحظه غالبًا'], traits),
         H('أنشطة ومحتوى مناسب'), TABLE(['النشاط', 'لماذا يناسب؟'], suits),
         H('جلسة نموذجية'), STEPS(session), TIPS(avoid, 'ما الذي أتجنبه؟'), EX(ex)], summ, sort)

